// Monta a "comanda da semana" de cada restaurante.
// Todos os números vêm das views do Supabase; aqui só formatamos (nenhuma conta nova).
const resumo = $('Resumo semanal').all().map(i => i.json);
const alertas = $('Alerta de caixa').all().map(i => i.json);
const promos = $('Promoções').all().map(i => i.json);
const canc = $('Cancelamentos altos').all().map(i => i.json);
const nomes = {1: 'Brasa Burger', 2: 'Marmita da Lu', 3: 'Forno Pampulha'};
const brl = v => 'R$ ' + Number(v).toLocaleString('pt-BR', {minimumFractionDigits: 2, maximumFractionDigits: 2});
const dm = s => { const [y, m, d] = s.split('-'); return `${d}/${m}`; };
const addDias = (s, n) => { const d = new Date(s + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const linha = (rotulo, valor) => rotulo.padEnd(20, ' ') + valor.padStart(12, ' ');
const out = [];
for (const id of [1, 2, 3]) {
  const semanas = resumo.filter(r => r.restaurante_id === id).sort((a, b) => b.semana.localeCompare(a.semana));
  const s = semanas[1] || semanas[0]; // última semana completa (a mais recente vai só até 31/10)
  const comanda = [
    '================================',
    `COMANDA DA SEMANA · ${dm(s.semana)}-${dm(addDias(s.semana, 6))}`,
    `${nomes[id]} · ${s.pedidos_entregues} pedidos`,
    '--------------------------------',
    linha('Faturamento bruto', brl(s.faturamento_bruto)),
    linha('(-) Descontos', brl(s.descontos)),
    linha('(-) Taxas', brl(s.taxas_plataforma)),
    linha('(-) Insumos', brl(s.custo_insumos)),
    '--------------------------------',
    linha('MARGEM REAL', brl(s.margem_contribuicao)),
    '================================',
  ].join('\n');
  const fatos = {
    restaurante: nomes[id],
    semana: s,
    caixa_proximos_30_dias: alertas.find(a => a.restaurante_id === id) || null,
    promocoes: promos.filter(p => p.restaurante_id === id),
    turnos_com_cancelamento_acima_de_8pct: canc.filter(c => c.restaurante_id === id),
  };
  out.push({json: {restaurante_id: id, comanda, fatos: JSON.stringify(fatos)}});
}
return out;

